def run(content):
    open('/tmp/t/x','w').write(content)
    env={**os.environ,'PATH':'/tmp/fakebin:'+os.environ['PATH']}
    subprocess.run(['./executable','solarized','-c','/tmp/t/x','-o','/tmp/t/x_out'], capture_output=True, env=env)
    return open('/tmp/t/x_out').read()

# Test client lines with varying vals - do they preserve extra?
for vals in ["#111111", "#111111 #222222", "#111111 #222222 #333333", "#111111 #222222 #333333 #444444", "#111111 #222222 #333333 #444444 #555555", "#111111 #222222 #333333 #444444 #555555 #666666"]:
