def norm(s):
    s=s.decode() if isinstance(s, bytes) else s
    s=re.sub(r"/tmp/i3-style/\d+/", "/tmp/i3-style/N/", s)
    s=re.sub(r"'main' \(\d+\)", "'main' (N)", s)
    return s

def test_apply(theme, cfg_content):
    open('/tmp/t/cfg_cmp','w').write(cfg_content)
    env={**os.environ,'PATH':'/tmp/fakebin:'+os.environ['PATH']}
    # Use separate outputs
    r1=subprocess.run(['./executable',theme,'-c','/tmp/t/cfg_cmp','-o','/tmp/t/out1'], capture_output=True, env=env)
    r2=subprocess.run(['./test_executable',theme,'-c','/tmp/t/cfg_cmp','-o','/tmp/t/out2'], capture_output=True, env=env)
    m = (norm(r1.stdout)==norm(r2.stdout) and norm(r1.stderr)==norm(r2.stderr) and r1.returncode==r2.returncode)
    try:
        f1=open('/tmp/t/out1').read()
    except: f1="<missing>"
    try:
        f2=open('/tmp/t/out2').read()
    except: f2="<missing>"
    fm = (f1==f2)
    print(f"theme {theme} stdout/stderr/exit {'OK' if m else 'FAIL'} file {'OK' if fm else 'FAIL'}")
    if not m:
        print(" orig out", repr(norm(r1.stdout)[:400]), "err", repr(norm(r1.stderr)[:400]))
        print(" test out", repr(norm(r2.stdout)[:400]), "err", repr(norm(r2.stderr)[:400]))
    if not fm:
        print(" orig file", repr(f1[:800]))
        print(" test file", repr(f2[:800]))
    for f in ['/tmp/t/out1','/tmp/t/out2']:
        try: os.remove(f)
        except: pass

# Test with various configs
